// Sample Epic giveaways, dated around today so the countdowns look right.
export function demoEpic(): { now: EpicGame[]; next: EpicGame[] } {
  const ms = (days: number) => Date.now() + days * day * 1000;
  const game = (title: string, slug: string, start: number, end: number, originalPrice: string): EpicGame => ({
    title,
    art: "",
    url: `https://store.epicgames.com/en-US/p/${slug}`,
    start: ms(start),
    end: ms(end),
    originalPrice,
  });
  return {
    now: [game("Sample Free Game One", "sample-one", -3, 4, "$24.99"), game("Sample Free Game Two", "sample-two", -3, 4, "$19.99")],
    next: [game("Mystery Game", "mystery", 4, 11, "")],
  };
}
